import json, math
from pathlib import Path
from pyscipopt import Model, quicksum
START='depot_start'; END='depot_end'; R=3960.0
def gc(a,b,r=R):
    lat1,lon1=a['latitude'],a['longitude']; lat2,lon2=b['latitude'],b['longitude']
    d=math.pi/180.0
    phi1=(90-lat1)*d; phi2=(90-lat2)*d; th1=lon1*d; th2=lon2*d
    cos=math.sin(phi1)*math.sin(phi2)*math.cos(th1-th2)+math.cos(phi1)*math.cos(phi2)
    cos=max(-1,min(1,cos))
    return math.acos(cos)*r
data=json.loads(Path('/root/data.json').read_text())
K=data['vehicle_count']; cap=data['vehicle_capacity']; w=data['penalty_weight']
depot={'latitude':float(data['depot']['latitude']),'longitude':float(data['depot']['longitude'])}
S=data['stations']; n=len(S)
loc=[{'latitude':float(s['latitude']),'longitude':float(s['longitude'])} for s in S]
trg=[int(s['net_rebalancing_target']) for s in S]
init=[int(s['initial_bikes']) for s in S]
scap=[int(s['station_capacity']) for s in S]
vehicles=range(K); stations=range(n)
from_nodes=[START,*stations]; to_nodes=[*stations,END]
arcs=[(i,j) for i in from_nodes for j in to_nodes if i!=j and not(i==START and j==END)]
def loc_node(node):
    if node in (START,END): return depot
    return loc[int(node)]
dist={(i,j):gc(loc_node(i),loc_node(j)) for i,j in arcs}
m=Model(); m.hideOutput(True); m.setParam('limits/time',30)
x={(v,i,j):m.addVar(vtype='B') for v in vehicles for i,j in arcs}
visit={(v,i):quicksum(x[v,i,j] for j in to_nodes if (i,j) in dist) for v in vehicles for i in stations}
svc={(v,i):m.addVar(vtype='I',lb=-cap,ub=cap) for v in vehicles for i in stations}
start={v:m.addVar(vtype='I',lb=0,ub=cap) for v in vehicles}
end={v:m.addVar(vtype='I',lb=0,ub=cap) for v in vehicles}
load={(v,i):m.addVar(vtype='I',lb=0,ub=cap) for v in vehicles for i in stations}
for v in vehicles:
    m.addCons(quicksum(x[v,START,j] for j in stations if (START,j) in dist)==1)
    m.addCons(quicksum(x[v,i,END] for i in stations if (i,END) in dist)==1)
    for i in stations:
        inc=quicksum(x[v,h,i] for h in from_nodes if (h,i) in dist and h!=i)
        out=quicksum(x[v,i,j] for j in to_nodes if (i,j) in dist and j!=i)
        m.addCons(inc==out)
        m.addCons(out<=1)
# MTZ
ord={(v,i):m.addVar(lb=0,ub=n) for v in vehicles for i in stations}
for v in vehicles:
    for i in stations:
        m.addCons(ord[v,i]<=n*visit[v,i])
        m.addCons(ord[v,i]>=visit[v,i])
    for i in stations:
        for j in stations:
            if i==j or (i,j) not in dist: continue
            m.addCons(ord[v,i]-ord[v,j]+n*x[v,i,j]<=n-1)
for v in vehicles:
    for i in stations:
        m.addCons(svc[v,i]<=cap*visit[v,i])
        m.addCons(svc[v,i]>=-cap*visit[v,i])
        m.addCons(load[v,i]<=cap*visit[v,i])
M=2*cap
for v in vehicles:
    for j in stations:
        if (START,j) in dist:
            m.addCons(load[v,j]-(start[v]+svc[v,j])<=M*(1-x[v,START,j]))
            m.addCons(load[v,j]-(start[v]+svc[v,j])>=-M*(1-x[v,START,j]))
    for i in stations:
        for j in stations:
            if i==j or (i,j) not in dist: continue
            m.addCons(load[v,j]-(load[v,i]+svc[v,j])<=M*(1-x[v,i,j]))
            m.addCons(load[v,j]-(load[v,i]+svc[v,j])>=-M*(1-x[v,i,j]))
    for i in stations:
        if (i,END) in dist:
            m.addCons(end[v]-load[v,i]<=M*(1-x[v,i,END]))
            m.addCons(end[v]-load[v,i]>=-M*(1-x[v,i,END]))
for i in stations:
    net=quicksum(svc[v,i] for v in vehicles)
    m.addCons(net<=init[i])
    m.addCons(net>=init[i]-scap[i])
    # force exact targets
    m.addCons(net==trg[i])
travel=quicksum(dist[i,j]*x[v,i,j] for v in vehicles for i,j in arcs)
m.setObjective(travel,'minimize')
m.optimize()
print('status',m.getStatus(),'sols',m.getNSols())
if m.getNSols()>0:
    print('travel',m.getObjVal())
